        }

        /* 触摸优化 */
        * {
          -webkit-tap-highlight-color: rgba(201, 170, 113, 0.2);
        }

        /* 输入框焦点优化 */
        input:focus, textarea:focus, select:focus {
          outline: 2px solid var(--color-primary);
          outline-offset: 2px;
        }

        /* 防止双击缩放 */
