          touch-action: manipulation;
        }

        /* 移动端特定的按钮状态 */
        .mobile-device .editor-btn:active,
        .mobile-device .main-menu-btn:active,
        .mobile-device .tab-button:active {
          background-color: rgba(201, 170, 113, 0.3);
          transform: scale(0.95);
        }

        /* 移动端滚动条完全隐藏 */
        .mobile-device ::-webkit-scrollbar {
          display: none;
        }

        .mobile-device * {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }

        /* 移动端文本选择优化 */
        .mobile-device .editor-item .item-description {
          -webkit-user-select: text;
          user-select: text;
        }

        /* 移动端loading状态优化 */
        .mobile-device .loading-placeholder {
          padding: 20px;
          font-size: 15px;
        }

        /* 移动端模态框进入/退出动画 */
        .mobile-device .modal-overlay {
          transition: opacity 0.2s ease;
        }

        .mobile-device .modal-content {
          transition: transform 0.2s ease, opacity 0.2s ease;
        }

        /* 移动端表单元素优化 */
        .mobile-device input[type="number"] {
          -moz-appearance: textfield;
          appearance: textfield;
        }

        .mobile-device input[type="number"]::-webkit-outer-spin-button,
        .mobile-device input[type="number"]::-webkit-inner-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }

        /* 移动端工具提示优化 */
        .mobile-device .attribute-tooltip {
          position: fixed;
          transform: translateX(-50%);
          left: 50%;
          top: auto;
          bottom: 10px;
          max-width: 90vw;
          z-index: 10000;
        }

        /* 移动端键盘打开状态优化 */
        .keyboard-open .global-controls {
          display: none !important;
        }

        .keyboard-open #floating-settings-btn,
        .keyboard-open #about-guixu-btn {
          display: none !important;
        }

        .keyboard-open .modal-content {
          max-height: 50vh !important;
          overflow-y: auto;
        }

        .keyboard-open .startup-choice-layout {
          height: 50vh !important;
        }

        /* 移动端安全区域适配 */
        .mobile-device {
          padding-bottom: env(safe-area-inset-bottom);
          padding-left: env(safe-area-inset-left);
          padding-right: env(safe-area-inset-right);
        }

        .mobile-device .global-controls {
          bottom: calc(15px + env(safe-area-inset-bottom));
        }

        .mobile-device #floating-settings-btn {
          bottom: calc(70px + env(safe-area-inset-bottom));
          left: calc(15px + env(safe-area-inset-left));
        }

        .mobile-device #about-guixu-btn {
          bottom: calc(70px + env(safe-area-inset-bottom));
          right: calc(15px + env(safe-area-inset-right));
        }

        /* 移动端滑动手势指示 */
        .mobile-device .modal-overlay::before {
          content: '';
          position: absolute;
          top: 10px;
          left: 50%;
          transform: translateX(-50%);
          width: 40px;
          height: 4px;
          background: rgba(255, 255, 255, 0.3);
          border-radius: 2px;
          z-index: 1;
        }
