        border: 1px solid rgba(201, 170, 113, 0.4);
      }
      .github-progress-bar {
        height: 100%;
        background: linear-gradient(90deg, #c9aa71, #daa520, #c9aa71);
        background-size: 200% 100%;
        animation: progressShine 2s linear infinite;
        transition: width 0.3s ease;
        border-radius: 12px;
        position: relative;
