er" id="wb-position-depth" class="modal-input" value="0"></div><div class="modal-form-group"><label for="wb-position-role">角色 (Role)</label><select id="wb-position-role" class="modal-select"><option value="system">系统 (System)</option><option value="user">用户 (User)</option><option value="assistant">助手 (Assistant)</option></select></div></div><div class="modal-form-grid"><div class="modal-form-group"><label>激活策略</label><button type="button" id="wb-strategy-toggle-btn" class="editor-btn" style="width:100%; margin-left:0;"></button></div><div class="modal-form-group" style="display: flex; flex-direction: column; justify-content: center; gap: 15px;"><div style="display: flex; align-items: center; gap: 10px;"><label class="toggle-switch"><input type="checkbox" id="wb-recursion-incoming"><span class="slider"></span></label><label for="wb-recursion-incoming" style="margin-bottom: 0; cursor: pointer;">不可递归</label></div><div style="display: flex; align-items: center; gap: 10px;"><label class="toggle-switch"><input type="checkbox" id="wb-recursion-outgoing"><span class="slider"></span></label><label for="wb-recursion-outgoing" style="margin-bottom: 0; cursor: pointer;">防止进一步递归</label></div><div style="display: flex; align-items: center; gap: 10px;"><label class="toggle-switch"><input type="checkbox" id="wb-modal-enabled"><span class="slider"></span></label><label for="wb-modal-enabled" style="margin-bottom: 0; cursor: pointer;">启用此条目</label></div></div></div><div class="modal-actions"><button type="button" id="wb-modal-cancel-btn" class="editor-btn">取消</button><button type="button" id="wb-modal-save-btn" class="editor-btn btn-primary">保存</button></div></form></div></div>
