    <script>
      // 类脑/旅程梦星作品，禁止二传，禁止商业化，均无偿免费开源分享
      (function () {
        // --- IndexedDB Manager for Save System ---
        const IndexedDBManager = {
            db: null,
            dbAvailable: false,

            async initializeDatabase() {
                try {
                    if (!window.indexedDB) {
                        console.warn('[归墟] IndexedDB不受支持，将使用localStorage');
                        this.dbAvailable = false;
                        return false;
                    }

                    if (typeof window.Dexie === 'undefined') {
                        console.warn('[归墟] Dexie库未加载，将使用localStorage');
                        this.dbAvailable = false;
                        return false;
                    }

                    this.db = new window.Dexie('GuixuSaveDB');
                    this.db.version(1).stores({
                        game_saves: 'id, timestamp, auto_generated, save_name'
                    });

                    await this.db.open();
                    this.dbAvailable = true;
                    console.log('[归墟] IndexedDB 数据库初始化成功');
                    return true;
                } catch (error) {
                    console.warn('[归墟] IndexedDB初始化失败，将使用localStorage:', error.message);
                    this.db = null;
                    this.dbAvailable = false;
                    return false;
                }
            },

            async saveToIndexedDB(saveData) {
                try {
                    if (!this.dbAvailable || !this.db) return false;
                    await this.db.game_saves.put(saveData);
                    return true;
                } catch (error) {
                    console.error('[归墟] IndexedDB存储失败:', error);
                    return false;
                }
            },

            async getAllFromIndexedDB() {
                try {
                    if (!this.dbAvailable || !this.db) return {};
                    const saves = await this.db.game_saves.orderBy('timestamp').reverse().toArray();
                    const result = {};
                    saves.forEach(save => {
                        result[save.id] = save;
                    });
                    return result;
                } catch (error) {
                    console.error('[归墟] IndexedDB读取失败:', error);
                    return {};
                }
            },

            async deleteFromIndexedDB(saveId) {
                try {
                    if (!this.dbAvailable || !this.db) return false;
                    await this.db.game_saves.delete(saveId);
                    return true;
                } catch (error) {
                    console.error('[归墟] IndexedDB删除失败:', error);
                    return false;
                }
            },

            async clearAllFromIndexedDB() {
                try {
                    if (!this.dbAvailable || !this.db) return false;
                    await this.db.game_saves.clear();
                    return true;
                } catch (error) {
                    console.error('[归墟] IndexedDB清空失败:', error);
                    return false;
                }
            }
        };

        // 存储模式管理器
        const StorageModeManager = {
            currentMode: 'localStorage', // 默认localStorage模式

            init() {
                // 从localStorage读取存储模式设置
                const savedMode = localStorage.getItem('guixu_storage_mode');
                if (savedMode) {
                    this.currentMode = savedMode;
                }

                // 初始化IndexedDB
                IndexedDBManager.initializeDatabase();

                // 设置切换开关状态
                this.updateSwitchUI();
            },

            async switchMode(newMode) {
                if (newMode === this.currentMode) return;

                // 显示切换确认
                const modeText = newMode === 'indexedDB' ? 'IndexedDB' : 'LocalStorage';
                const confirmText = `确定要切换到 ${modeText} 存储模式吗？\n\n注意：不同存储模式下的存档数据是分离的。切换后需要重新刷新"读档 / 管理"界面。`;

                if (!await guiXuConfirm(confirmText)) {
                    // 用户取消，恢复开关状态
                    this.updateSwitchUI();
                    return;
                }

                this.currentMode = newMode;
                localStorage.setItem('guixu_storage_mode', newMode);
                this.updateSwitchUI();

                // 刷新存档列表
                showSaveLoadManager();

                await guiXuAlert(`已切换到 ${modeText} 存储模式。`);
            },

            updateSwitchUI() {
                const switchInput = document.getElementById('storage-mode-switch');
                const label = document.getElementById('storage-mode-label');

                if (switchInput) {
                    switchInput.checked = this.currentMode === 'indexedDB';
                }
                if (label) {
                    label.textContent = this.currentMode === 'indexedDB' ? 'IndexedDB' : 'LocalStorage';
                }
            }
        };

        // --- 全局配置 ---
        const LOREBOOK_NAME = '【归墟扩展】天赋出生';
        const WORLDBOOK_LOREBOOK_NAME = '1归墟';

        //GitHub 资料库信息
        const githubID = 'ab003317';
        const githubLocation = { repo: 'GuixuFrontend', branch: 'main', basePath: 'Guixu' };

        // --- 新增：游戏难度规则配置 ---
        const DIFFICULTY_LORE_ENTRIES = [
            '【cot】【简单】必要关键cot（1-5）',
            '【cot】【标配】【困难】必要关键cot（1-6）',
            '【系统】【标配】超级无敌合理性审查',
            '【系统】【标配】合理性审查【修改】',
            '【cot】合理性审查加强'
        ];

        const GAME_DIFFICULTY_DEFINITIONS = {
            easy: {
                id: 'easy',
                name: '简单模式',
                description: '爽文模式。适合想要体验剧情、轻松游玩的玩家，AI会像一个友好的故事引导者来推进剧情。',
                entriesToEnable: [
                    '【cot】【简单】必要关键cot（1-5）'
                ]
            },
            normal: {
                id: 'normal',
                name: '普通模式',
                description: '标准的游戏模式。世界遵循其自身的逻辑，玩家需要谨慎思考。',
                entriesToEnable: [
                    '【cot】【标配】【困难】必要关键cot（1-6）',
                    '【系统】【标配】合理性审查【修改】'
                ]
            },
            hard: {
                id: 'hard',
                name: '困难模式',
                description: '一个残酷、真实、充满恶意的修仙世界。生存本身就是一种挑战，每一次行动都可能带来灾难性的后果。',
                entriesToEnable: [
                    '【cot】【标配】【困难】必要关键cot（1-6）',
                    '【系统】【标配】合理性审查【修改】',
                    '【系统】【标配】超级无敌合理性审查',
                    '【cot】合理性审查加强'
                ]
            }
        };

        let CloudDatabaseCurrentPage = 'talent';

        let latestCloudData = null;
        // 云端新增的待确认（Pending）缓存，按页面分类保存
        const cloudPending = { talent: [], background: [], worldbook: [], preset: [] };
        let lastPendingAnchorId = '';
        // GitHub数据缓存
        const githubCache = new Map();
        const CACHE_EXPIRY = 5 * 60 * 1000; // 5分钟缓存

        async function fetchJson(url, useCache = true) {
          // 检查缓存
          if (useCache && githubCache.has(url)) {
            const cached = githubCache.get(url);
            if (Date.now() - cached.timestamp < CACHE_EXPIRY) {
              console.log(`[缓存命中] ${url}`);
              return cached.data;
            }
            githubCache.delete(url);
          }

          // 添加超时控制
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 15000); // 15秒超时

          try {
            const res = await fetch(url, { 
              headers: { 'Accept': 'application/vnd.github+json' },
              signal: controller.signal
            });
            clearTimeout(timeoutId);

            if (!res.ok) throw new Error(`请求失败 ${res.status}: ${url}`);
            const data = await res.json();

            // 存入缓存
            if (useCache) {
              githubCache.set(url, { data, timestamp: Date.now() });
            }

            return data;
          } catch (error) {
            clearTimeout(timeoutId);
            if (error.name === 'AbortError') {
              throw new Error(`请求超时: ${url}`);
            }
            throw error;
          }
        }

        const fetchGitHubData = {
          // 初始化属性
          githubID: githubID,
          githubLocation: `${githubLocation.repo}/${githubLocation.branch}/${githubLocation.basePath}`,

          // 进度更新函数
          _updateProgress(percent, message) {
            const container = document.getElementById('github-progress-container');
            const bar = document.getElementById('github-progress-bar');
            const text = document.getElementById('github-progress-text');
            const info = document.getElementById('github-progress-info');

            if (container) container.style.display = 'block';
            if (bar) bar.style.width = `${percent}%`;
            if (text) text.textContent = `${percent}%`;
            if (info) info.textContent = message || `加载中... ${percent}%`;
          },

          _hideProgress() {
            const container = document.getElementById('github-progress-container');
            if (container) {
              setTimeout(() => {
                container.style.display = 'none';
              }, 500);
            }
          },
          // 统一提取函数：优先使用显式字段，其次解析括号格式名称
          _extractMeta(raw, expectedTypeZh) {
            const aliasAuthor = raw.author || raw.creator || raw.Author || raw.authorName || raw.作者 || '';
            const aliasSeries = raw.series || raw.Series || raw.系列 || '';
            let baseName = raw.name || raw.id || '';
            let finalAuthor = aliasAuthor;
            let finalSeries = aliasSeries;
            if (baseName && baseName.startsWith('【')) {
              try {
                const parsed = WorldBookManager.parseCommentTitle(baseName);
                if (parsed && parsed.name) {
                  // 类型匹配或未提供期望类型时采用解析结果
                  if (!expectedTypeZh || parsed.type === expectedTypeZh || parsed.type === '世界书') {
                    baseName = parsed.name;
                    if (!finalAuthor && parsed.author && parsed.author !== '未知') finalAuthor = parsed.author;
                    if (!finalSeries && parsed.series) finalSeries = parsed.series;
                  }
                }
              } catch (e) { /* 忽略解析错误 */ }
            }
            return {
              name: baseName,
              author: (finalAuthor || '').trim() || '未知',
              series: (finalSeries || '').trim(),
            };
          },

          async listFolder(folder) {
            // 解析githubLocation字符串
            const locationParts = this.githubLocation.split('/');
            const repo = locationParts[0] || 'GuixuFrontend';
            const branch = locationParts[1] || 'main';
            const basePath = locationParts.slice(2).join('/') || 'Guixu';

            const api = `https://api.github.com/repos/${this.githubID}/${repo}/contents/${basePath}/${folder}?ref=${branch}`;
            const items = await fetchJson(api);
            return Array.isArray(items) ? items.filter(i => i.type === 'file' && /\.json$/i.test(i.name)) : [];
          },
          async loadAllData() {
            try {
              const [talentFiles, backgroundFiles, worldbookFiles, presetFiles] = await Promise.all([
                this.listFolder('talent'),
                this.listFolder('background'),
                this.listFolder('worldbook'),
                this.listFolder('preset'),
              ]);
              const fetchFiles = async (files) => {
                const results = [];
                for (const file of files) {
                  try {
                    const data = await fetchJson(file.download_url);
                    results.push({ ...data, _sourceFile: file.name });
                  } catch (e) {
                    console.warn('解析 GitHub JSON 失败:', file.name, e);
                  }
                }
                return results;
              };
              const [talents, backgrounds, worldbooks, presets] = await Promise.all([
                fetchFiles(talentFiles),
                fetchFiles(backgroundFiles),
                fetchFiles(worldbookFiles),
                fetchFiles(presetFiles),
              ]);
              return {
                talents: talents.map(t => {
                  const meta = this._extractMeta(t, '天赋');
                  return {
                    id: t.id || meta.name || (t._sourceFile || '').replace(/\.json$/i, ''),
                    name: meta.name || (t._sourceFile || '').replace(/\.json$/i, ''),
                    author: meta.author,
                    series: meta.series,
                    quality: t.quality || '凡品',
                    cost: Number(t.cost) || 0,
                    description: t.description || '',
                  };
                }),
                backgrounds: backgrounds.map(b => {
                  const meta = this._extractMeta(b, '背景');
                  return {
                    id: b.id || meta.name || (b._sourceFile || '').replace(/\.json$/i, ''),
                    name: meta.name || (b._sourceFile || '').replace(/\.json$/i, ''),
                    author: meta.author,
                    series: meta.series,
                    quality: b.quality || '凡品',
                    description: b.description || '',
                    initialResources: Array.isArray(b.initialResources) ? b.initialResources : [],
                  };
                }),
                worldbookEntries: worldbooks.map(w => {
                  const meta = this._extractMeta(w, '世界书');
                  return {
                    id: w.id || meta.name || (w._sourceFile || '').replace(/\.json$/i, ''),
                    name: meta.name || (w._sourceFile || '').replace(/\.json$/i, ''),
                    author: meta.author,
                    series: meta.series,
                    quality: w.quality || '无',
                    description: w.description || w.content || '',
                    content: w.content || w.description || '',
                    enabled: typeof w.enabled === 'boolean' ? w.enabled : false,
                    strategy: w.strategy || null,
                    position: w.position || null,
                  };
                }),
                presets: presets.map(p => {
                  // 检测并处理预设包格式 {type: 'preset', data: {...}}
                  let actualData, isPresetPackage = false;
                  if (p.type === 'preset' && p.data) {
                    // 新格式预设包
                    actualData = p.data;
                    isPresetPackage = true;
                  } else {
                    // 传统单预设格式
                    actualData = p;
                  }

                  return {
                    id: actualData.id || actualData.name || (p._sourceFile || '').replace(/\.json$/i, ''),
                    name: actualData.name || (p._sourceFile || '').replace(/\.json$/i, ''),
                    author: actualData.author || '未知',
                    series: actualData.series || '',
                    description: actualData.description || '',
                    points: Number(actualData.points) || 40,
                    // 保留原始格式信息，供confirm处理使用
                    type: p.type,
                    data: p.data,
                    attributes: actualData.attributes || {},
                    requiredTalents: Array.isArray(actualData.requiredTalents) ? actualData.requiredTalents : [],
                    optionalTalents: Array.isArray(actualData.optionalTalents) ? actualData.optionalTalents : [],
                    // 保留完整原始数据供确认处理使用
                    _originalData: p,
                    _isPresetPackage: isPresetPackage,
                    localTalents: Array.isArray(actualData.localTalents) ? actualData.localTalents : [],
                    localBackgrounds: Array.isArray(actualData.localBackgrounds) ? actualData.localBackgrounds : [],
                    worldBook: Array.isArray(actualData.worldBook) ? actualData.worldBook : [],
                  };
                }),
              };
            } catch (error) {
              console.error('从 GitHub 加载数据失败:', error);
              return { talents: [], backgrounds: [], worldbookEntries: [], presets: [] };
            }
          },
          async loadPageData(page, showProgress = false) {
            try {
              const typeToFolder = { talent: 'talent', background: 'background', worldbook: 'worldbook', preset: 'preset' };
              const folder = typeToFolder[page] || 'talent';

              // 显示进度条
              if (showProgress) {
                this._updateProgress(0, `正在获取${page}文件列表...`);
              }

              const files = await this.listFolder(folder);

              if (showProgress) {
                this._updateProgress(20, `找到 ${files.length} 个文件，开始下载...`);
              }

              const fetchFiles = async (items) => {
                const results = [];
                const totalFiles = items.length;
                let completedFiles = 0;

                // 使用并发请求，每次最多5个并发
                const concurrencyLimit = 5;
                for (let i = 0; i < items.length; i += concurrencyLimit) {
                  const batch = items.slice(i, i + concurrencyLimit);
                  const batchPromises = batch.map(async file => {
                    try {
