            const match2 = comment.match(/^【(天赋|背景|预设|世界书)】([^【]+)【([^】]+)】$/);
            const matchNew = comment.match(/^【(天赋|背景|预设|世界书)】【([^】]+)】【([^】]+)】(.+)$/);

            if (matchNew) {
              result.type = matchNew[1];
              // 检查是否是作者重复的情况（如【天赋】【Ab003317】【Ab003317】绝处逢生）
              if (matchNew[2] === matchNew[3]) {
                // 第二、三个括号内容相同，说明是【类型】【作者】【作者】名字的格式
                result.series = '';  // 系列为空
                result.author = matchNew[2];  // 作者取第二个括号的内容
                result.name = matchNew[4].trim();
              } else {
                // 正常的【类型】【系列】【作者】名字格式
                result.series = matchNew[2];
                result.author = matchNew[3];
                result.name = matchNew[4].trim();
              }
              return result;
            }
            if (matchExtendedWB) {
                result.type = matchExtendedWB[1];
                result.series = matchExtendedWB[2];
                result.author = matchExtendedWB[3];
                result.name = matchExtendedWB[4].trim();
            } else if (match1) {
              result.type = match1[1];
              result.series = match1[2];
              result.name = match1[3].trim();
              result.author = match1[4];
            } else if (match2) {
              result.type = match2[1];
              result.name = match2[2].trim();
              result.author = match2[3];
