  author: resolvedAuthor,
  series: titleInfo.series || yamlData.系列 || '',
  quality: yamlData.品阶 || '凡品', // <--- 修改这里
  cost: parseInt(yamlData.消耗点数) || 0,
  description: yamlData.描述 || '',
  isFromWorldBook: true,
  originalComment: entry.name,
