});
                      worldbookEntries.push(entry);
                  } else if (entry.name.startsWith('【背景】')) {
                      const parsedName = titleInfo.name || entry.name.replace(/^【背景】/, '').split('【')[0].trim();
                      const resolvedAuthor = (titleInfo.author && titleInfo.author !== '未知') ? titleInfo.author : (yamlData.作者 || '未知');
                      backgrounds.push({
  id: parsedName,
  name: parsedName,
  author: resolvedAuthor,
  series: titleInfo.series || yamlData.系列 || '',
  quality: yamlData.品阶 || '凡品', // <--- 修改这里
  description: yamlData.描述 || '',
  initialResources: yamlData.初始资源 || [],
  isFromWorldBook: true,
  originalComment: entry.name,
  uid: entry.uid,
});
              worldbookEntries.push(entry);
          } else if (entry.name.startsWith('【预设】')) {
              const parsedName = titleInfo.name || entry.name.replace(/^【预设】/, '').split('【')[0].trim();
              // 安全解析JSON格式的字段
              const parseJsonField = (field) => {
                if (!field) return [];
                if (typeof field === 'string') {
                  try {
                    return JSON.parse(field);
                  } catch (e) {
                    console.warn('解析JSON字段失败:', field, e);
                    return [];
                  }
                }
                return field;
              };

              presets.push({
                id: parsedName,
                name: parsedName,
                author: titleInfo.author,
                series: titleInfo.series || yamlData.系列 || '',
                points: parseInt(yamlData.点数) || 40,
                description: yamlData.描述 || '',
                attributes: parseJsonField(yamlData.属性分配) || {},
                // 预设只包含基本信息，专属天赋/背景作为单独的世界书条目存在
                requiredTalents: parseJsonField(yamlData.必选天赋) || [],
                optionalTalents: parseJsonField(yamlData.可选天赋) || [],
                localTalents: [], // 专属天赋从世界书中动态获取
                localBackgrounds: [], // 专属背景从世界书中动态获取
                worldBook: [], // 世界书条目从世界书中动态获取
                isFromWorldBook: true,
                originalComment: entry.name,
                uid: entry.uid,
                enabled: entry.enabled,
              });
              worldbookEntries.push(entry);
          } else {
            worldbookEntries.push(entry);
          }
        } catch (e) {
          console.warn('解析世界书条目失败:', entry.name, e);
        }
      }
      return { talents, backgrounds, presets, worldbookEntries, isEmpty: false };
    } catch (error) {
      console.error('从世界书加载数据失败:', error);
      return { talents: [], backgrounds: [], presets: [], worldbookEntries: [], isEmpty: true };
    }
  },

  // 一次性修复：为历史数据补全作者（当标题无作者且 YAML 内含 作者 字段）
  async migrateRepairMissingAuthors() {
    try {
      await this._saveOrUpdateWith(async worldbook => {
        let changed = false;
        for (const entry of worldbook) {
          if (!entry || !entry.name || !entry.content) continue;
          if (!/^【(天赋|背景)】/.test(entry.name)) continue;
          const parsed = this.parseCommentTitle(entry.name);
            if (parsed.author && parsed.author !== '未知') continue; // 已有作者
          const yaml = YAMLParser.parse(entry.content);
          const yamlAuthor = yaml.作者;
          if (yamlAuthor && yamlAuthor !== '未知') {
            // 重建标题
            const typeZh = parsed.type || (entry.name.startsWith('【天赋】') ? '天赋' : '背景');
            const internalType = typeZh === '天赋' ? 'talent' : 'background';
            const newTitle = this.generateCommentTitle(internalType, parsed.name || entry.name, yamlAuthor, parsed.series || yaml.系列 || '');
            if (newTitle !== entry.name) {
              entry.name = newTitle;
              changed = true;
              console.log('[修复] 补全作者 ->', newTitle);
            }
          }
        }
        return changed ? worldbook : worldbook;
      });
    } catch (e) {
      console.warn('迁移补全作者失败:', e);
    }
  },

