  async saveWorldBookEntry(entryData) {
    // --- 修复: 导入时 author 丢失/未写入标题 ---
    // 允许外部传入: { name, author, series, content, ... }
    // 若 name 未包含花括号格式，或缺失作者段，自动重建。
    const originalName = entryData.name || entryData.id || '未命名条目';
    const suppliedAuthor = (entryData.author || '').trim();
    const suppliedSeries = (entryData.series || '').trim();
    const hasBracketFormat = /^【.+】/.test(originalName);
    let rebuilt = false;
    if (!hasBracketFormat) {
      // 纯名称 -> 生成标准标题（世界书类型固定）
      entryData.name = this.generateCommentTitle('worldbook', originalName, suppliedAuthor || '未知', suppliedSeries);
      rebuilt = true;
    } else {
      // 已有格式，但可能缺作者。解析后判断是否需要补全。
      const parsed = this.parseCommentTitle(originalName);
      if (parsed.type === '世界书') {
        if ((suppliedAuthor && suppliedAuthor !== '未知') && (parsed.author === '未知' || !originalName.includes(`【${suppliedAuthor}】`))) {
          // 重新生成，优先保留 series / name
          entryData.name = this.generateCommentTitle('worldbook', parsed.name || originalName, suppliedAuthor, suppliedSeries || parsed.series);
          rebuilt = true;
        }
      }
    }
    if (rebuilt) {
      console.log('[WorldBookEntry] 标题已自动生成/补全 author:', entryData.name);
    }
    // 判断是否是【世界书】类条目（使用最终 name）
    const isWorldBookEntry = entryData.name && entryData.name.startsWith('【世界书】');
    const targetLorebookName = isWorldBookEntry ? this.WORLDBOOK_LOREBOOK_NAME : this.LOREBOOK_NAME;
    if (!entryData.uid) entryData.uid = this.generateUid();

    return this._saveOrUpdateWithBook(targetLorebookName, worldbook => {
      const entryIndex = entryData.uid ? worldbook.findIndex(e => String(e.uid) === String(entryData.uid)) : -1;
      if (entryIndex > -1) {
        // 更新现有条目
        worldbook[entryIndex] = { ...worldbook[entryIndex], ...entryData };
      } else {
        // 检查是否已存在同名条目
        const duplicateIndex = worldbook.findIndex(e => e.name === entryData.name);
        if (duplicateIndex > -1) {
          // 覆盖同名条目
          worldbook[duplicateIndex] = { ...worldbook[duplicateIndex], ...entryData };
          console.log(`覆盖同名世界书条目: ${entryData.name}`);
        } else {
          // 添加新条目
          worldbook.push(entryData);
          console.log(`添加新世界书条目: ${entryData.name}`);
        }
      }
      return worldbook;
    });
  },

  async deleteEntryByUid(uid) {
  if (typeof uid === 'undefined' || uid === null) {
    console.warn('[归墟编辑器] deleteEntryByUid 接收到无效 UID，尝试回退删除逻辑。');
    return false; // 现在始终为所有条目补全 uid，因此理论上不再触发
  }
    try {
        // 先尝试从主世界书删除
        let deleted = await this._saveOrUpdateWith(worldbook => {
            const originalLength = worldbook.length;
            const filtered = worldbook.filter(e => String(e.uid) !== String(uid));
            return { worldbook: filtered, found: filtered.length < originalLength };
        });

        if (deleted && deleted.found) {
            return true;
        }

        // 如果主世界书中没找到，尝试从【世界书】专用存储删除
        deleted = await this._saveOrUpdateWithBook(this.WORLDBOOK_LOREBOOK_NAME, worldbook => {
            const originalLength = worldbook.length;
            const filtered = worldbook.filter(e => String(e.uid) !== String(uid));
            return { worldbook: filtered, found: filtered.length < originalLength };
        });

        return deleted && deleted.found;
    } catch (error) {
        console.error(`Failed to delete worldbook entry with UID: ${uid}`, error);
        return false;
    }
  },
};

