let saveDebounceTimer = null;

// --- 自定义模态框 ---
function showCustomModal(options) {
  return new Promise(resolve => {
    const config = {
      title: '提示',
      content: '',
      buttons: [{ text: '确认', value: true, class: 'btn-primary' }],
      inputType: null, 
      inputValue: '',
      ...options,
    };

    const existingModal = document.getElementById('custom-modal-overlay');
    if (existingModal) {
      existingModal.remove();
    }

    const modalOverlay = document.createElement('div');
    modalOverlay.id = 'custom-modal-overlay';
    modalOverlay.className = 'modal-overlay';
    modalOverlay.style.display = 'flex';
    modalOverlay.style.zIndex = '20000'; 

    let inputHtml = '';
    if (config.inputType) {
      if (config.inputType === 'textarea') {
        inputHtml = `
          <div class="modal-form-group">
            <textarea id="custom-modal-input" class="modal-textarea" style="height: 200px;">${config.inputValue}</textarea>
          </div>`;
      } else {
        inputHtml = `
          <div class="modal-form-group">
            <input type="${config.inputType}" id="custom-modal-input" class="modal-input" value="${config.inputValue}">
          </div>`;
      }
    }

    modalOverlay.innerHTML = `
      <div class="modal-content" style="max-width: 600px; max-height: 80vh; overflow-y: auto;">
        <h2 class="modal-title" style="color: #c9aa71; border-bottom: 1px solid #8b7355; margin-bottom: 20px; padding-bottom: 10px;">${config.title}</h2>
        <div class="modal-body" style="padding: 0 0 20px; color: var(--color-text-light); line-height: 1.6; word-wrap: break-word;">${config.content}</div>
        ${inputHtml}
        <div class="modal-footer" style="justify-content: center; border-top: 1px solid #8b7355; margin-top: 20px; padding-top: 15px;">
          ${config.buttons
            .map(
              btn =>
                `<button class="editor-btn ${btn.class || ''}" data-value="${btn.value}">${btn.text}</button>`
            )
            .join('')}
        </div>
      </div>
    `;

    document.body.appendChild(modalOverlay);
    const modalContent = modalOverlay.querySelector('.modal-content');
    modalContent.style.animation = 'fadeIn 0.3s ease forwards';

    modalOverlay.addEventListener('click', e => {
      const target = e.target;
      if (target.matches('.editor-btn')) {
        const buttonValue = target.dataset.value;
        let resolveValue;

        if (buttonValue === 'true') resolveValue = true;
        else if (buttonValue === 'false') resolveValue = false;
        else resolveValue = buttonValue;

        if (config.inputType) {
          const input = document.getElementById('custom-modal-input');
          if (buttonValue !== 'cancel') {
             resolve({ button: buttonValue, value: input.value });
          } else {
             resolve({ button: 'cancel', value: null });
          }
        } else {
          resolve(resolveValue);
        }
        modalOverlay.remove();
      }
    });
  });
}

