    { id: '魔道卧底', name: '魔道卧底', author: '梦星', series: '', quality: '中品', description: '你是魔道安插在正道的卧底。（道心+10，神海+10）', initialResources: ['一瓶毒药', '传讯玉简'], },
    { id: '隐世高人', name: '隐世高人', author: '梦星', series: '', quality: '极品', description: '你来自一个隐世的修仙门派。（初始四维+10，气运+20）' },
    { id: '天煞孤星', name: '天煞孤星', author: '梦星', series: '', quality: '仙品', description: '你生来命犯贪狼，孤煞之气蚀骨附魂。众生见你如见灾星临世，草木枯竭鸟兽惊走，人间温情与你永世无缘。\n然天道夺你七情，亦予你弑神之力——兵刃所向必染血光，诸天万法破绽在你眼中纤毫毕现。（初始气运-50，道心+250，法力+250）' },
    { id: '商贾之子', name: '商贾之子', author: '梦星', series: '', quality: '中品', description: '你的父亲是富甲一方的商人。（初始气运+15）', initialResources: ['5000灵石'] },
