    { id: '散修传人', name: '散修传人', author: '梦星', series: '', quality: '上品', description: '你得到了一位散修的传承。（初始道心+30，神海+20）', initialResources: ['残缺的功法玉简'] },
    { id: '重生之人', name: '重生之人', author: '梦星', series: '', quality: '天品', description: '你带着前世的记忆重生了。（初始神海+200）', initialResources: [] },
    { id: '超可爱的白毛弱受成年合法小萝莉（女性）', name: '超可爱的白毛弱受成年合法小萝莉（女性）', author: '梦星', series: '', quality: '神品', description: '你是一个超可爱的白毛弱受成年合法小萝莉（女性）。1月1日，今天出门遇到了个怪事，一个叫慕轩翎的白毛红瞳清冷禁欲系姐姐忽然找到我，说我很可爱，还给我一颗“梦星妙妙糖”，很甜。1月2日，不对！我怎么昏过去了，不对！这里怎么这么暗？不对！那个大姐姐怎么在这里！1月3日，我绝对不会屈服的！可恶的慕轩翎！我绝对不会再吃你的“梦星妙妙糖”了。“唔呜呜....怎么是....用嘴啊....我不要吃...”身体开始奇怪了，怎么办！唔，但似乎很甜欸，之前的“梦星妙妙糖”好像不是这个味道欸，奇怪。1月4日，大姐姐是坏人，居然用那种地方，但是她好温柔啊，虽然看起来冷冰冰的。1月5日，不想动了，身体好酸，但很舒服。1月6日，白星啊白星，你不能再这么沉沦下去了，你必须奋斗起来，狠狠反抗慕轩翎的压迫。1月7日，好舒服，不想动了。1月8日，好舒服。1月9日，好舒服。1月10日....试试梦星妙妙糖，看看感觉怎么样。1月11日，很舒服，继续在轩翎姐姐的“仙翎宫”开摆吧，她说她是什么飞升期，好像很厉害的样子，唔，不管了，其他什么的，算啦！（百合导向，**禁止扶她**，禁止男性，梦星妙妙糖是春药+迷药，还具有大幅度增加修为、神海、法力，降低道心，空速的作用）（初始修为增加，神海+500，法力+500，道心-200，空速-200）', unlocked: false },
    { id: '混沌三宝', name: '混沌三宝', author: '梦星', series: '', quality: '神品', description: '你拥有混沌体、混沌灵根、混沌经。（初始四维+250，修炼速度+100%，功法自带成长）', unlocked: false },
    { id: '肖星', name: '肖星', author: '梦星', series: '', quality: '神品', description: '来自2025年的现代地球穿越者，穿越修仙世界。\n修为：神桥境三步\n肖星在一座大山上醒来，此处灵气十足，仙气缥缈，肖星决定在这开创属于自己的宗门，取名白虎宗，寓意宗门只收女弟子，且必须没有阴毛，皆为光滑白虎，白虎宗定义非邪魔外道，即便宗门行内部双修功法修炼，也仅仅局限在宗门女弟子与宗主之间发生，不强迫，不要挟，外拜入白虎宗之前均告知，全凭自愿；\n白虎宗弟子外出行走，不偷不抢，光明正大，行仗义之事，羞于邪魔外道为伍。\n肖星构思好这些规矩后，准备建立宗门。（初始境界为神桥境）', unlocked: false },
    { id: '落月宗遗孤', name: '落月宗遗孤', author: '梦星', series: '', quality: '上品', description: '你是落月宗的最后一名弟子，宗门在一场浩劫中覆灭，只有你侥幸逃脱。身负血海深仇，怀着复仇的决心踏上修仙之路。（道心+30，法力+20）', unlocked: false },
    { id: '罪臣之后', name: '罪臣之后', author: '梦星', series: '', quality: '中品', description: '你的先辈曾是朝中重臣，后因罪被贬，家族受尽白眼。（气运-10，道心+30）' },
    { id: '青楼艺妓', name: '青楼艺妓', author: '梦星', series: '', quality: '中品', description: '你虽身处烟花之地，却洁身自好，卖艺不卖身，暗中积蓄力量。（神海+10，道心+10）' },
    { id: '行脚商人', name: '行脚商人', author: '梦星', series: '', quality: '中品', description: '你常年奔波于各地，见多识广，消息灵通。（神海+20）' },
    { id: '守墓人', name: '守墓人', author: '梦星', series: '', quality: '上品', description: '你世代守护着一座古老的陵墓，知晓许多不为人知的秘密。（神海+30，道心+20）' },
    { id: '死而复生', name: '死而复生', author: '梦星', series: '', quality: '天品', description: '你曾经历过一次死亡，却又离奇复活，对生死有独特的感悟。（道心+150，神海+50）' },
    { id: '异域来客', name: '异域来客', author: '梦星', series: '', quality: '天品', description: '你并非此界中人，意外流落至此，身怀异域的传承。（初始四维+50）' },
    { id: '铸剑山庄', name: '铸剑山庄', author: '梦星', series: '', quality: '上品', description: '你出身于以铸剑闻名的山庄，从小耳濡目染，精通锻造之术。（法力+30，神海+20）' },
    { id: '预言之子', name: '预言之子', author: '梦星', series: '', quality: '仙品', description: '古老的预言中提到了你的降生，你的命运与整个世界的未来息息相关。（气运+500）' },
    { id: '魁首弟子', name: '魁首弟子', author: '梦星', series: '', quality: '天品', description: '你是某个顶尖宗门掌门的亲传大弟子，备受期待，也备受瞩目。（初始四维+50，气运+50）' },
    { id: '凡人逆袭', name: '凡人逆袭', author: '梦星', series: '', quality: '极品', description: '你本是毫无灵根的凡人，却凭借大毅力、大智慧，硬生生踏上了修仙之路。（道心+100）' },
    { id: '天道图书馆管理员', name: '天道图书馆管理员', author: '梦星', series: '', quality: '仙品', description: '你曾是管理着记录三千世界信息的图书馆的管理员，脑中记下了无数功法秘闻，但因为偷看禁忌知识而被贬下凡间。（神海+500）' },
    { id: '失落文明的幸存者', name: '失落文明的幸存者', author: '梦星', series: '', quality: '天品', description: '你来自一个科技与修仙结合的失落文明，掌握着独特的知识体系。（神海+150，法力+50）' },
    { id: '“主角”的退婚对象', name: '“主角”的退婚对象', author: '梦星', series: '', quality: '上品', description: '你曾是某个“气运之子”的未婚夫/妻，因为某些原因退婚，结果对方三十年河东三十年河西，现在回来找你麻烦了。（气运-20，道心+70）' },
    { id: '仙人棋子', name: '仙人棋子', author: '梦星', series: '', quality: '仙品', description: '你的人生是一盘棋，由一位高高在上的仙人布局，你的一举一动都可能是在完成某个你不知道的宏大计划。（气运+300，道心+200）' },
    { id: '故事的说书人', name: '故事的说书人', author: '梦星', series: '', quality: '极品', description: '你是一个说书人，你所讲述的故事，有可能会在现实中成真。（神海+50，气运+50）' },
    { id: '天魔转世', name: '天魔转世', author: '梦星', series: '', quality: '仙品', description: '你是上古天魔的一缕残魂转世，天生对魔道功法有极高的亲和力，但也要时刻提防被魔性吞噬。（法力+300，道心-100，神海+300）' },
    { id: '器灵化形', name: '器灵化形', author: '梦星', series: '', quality: '天品', description: '你本是一件神兵的器灵，机缘巧合之下得以化为人形，但本体依旧存在，与你性命交修。（法力+100，道心+100）' },
    { id: '被封印的古神', name: '被封印的古神', author: '梦星', series: '', quality: '神品', description: '你是一个被遗忘的古神，力量被层层封印，化为凡胎，需要一步步解开封印才能恢复力量。（初始四维极低，但成长潜力巨大）' },
    { id: '历史的修正者', name: '历史的修正者', author: '梦星', series: '', quality: '仙品', description: '你是一个神秘组织的成员，负责穿越到不同的时间节点，修正被扰乱的历史，确保世界线不至于崩溃。（神海+300，空速+200）' },
    { id: '终焉的观测者', name: '终焉的观测者', author: '梦星', series: '', quality: '神品', description: '你见证了无数个世界的诞生与毁灭，如今来到这个新世界，只是为了观测它的结局。（道心+1000）' },
    { id: '半人半妖', name: '半人半妖', author: '梦星', series: '', quality: '上品', description: '你的血脉中一半是人，一半是妖，这让你在两个种族之间都难以立足，但同时也可能让你拥有两种血脉的优势，你背负着整个妖族的命运。（法力+30，道心+20）' },
    { id: '上古之人', name: '上古之人', author: '梦星', series: '', quality: '天品', description: '你从一个古老的遗迹中苏醒，对这个时代一无所知，但你的身体里却蕴含着上古时代的力量和秘密。（初始四维+50）' },
    { id: '遮天来客', name: '遮天来客', author: '梦星', series: '', quality: '仙品', description: '你来自《遮天》的世界，携带着那个世界的独特功法和体质，降临在这个新的修仙宇宙。（法力+300，道心+200）' },
    { id: '烙印战士', name: '烙印战士', author: '梦星', series: '', quality: '仙品', description: '携带一个霸王之卵，需要在特定的时间地点献祭他人灵魂方可解放，解放后玩家获得“神之力”。弊端：烙印之痛会在夜间打开阴界之门，吸引以它为食的怨灵和魔兽，整夜不得安眠，在高怨气之地也会吸引出大怨灵缠身（日间会削弱怨灵）。优点：超强体魄以及体术和剑术，以及超凡的个人魅力和统率力，随身携带一把大的不像样的斩龙剑（对怨灵有效）。（法力+400，道心+100，气运-100）' },
    { id: '机械飞升', name: '机械飞升', author: '梦星', series: '', quality: '仙品', description: '你来自一个高度发达的科技文明，通过机械改造放弃了肉体，获得了强大的计算力和适应性，但失去了情感和灵性的感悟。（神海+400，法力+100，道心-100）' },
    { id: '末法时代遗民', name: '末法时代遗民', author: '梦星', series: '', quality: '极品', description: '你来自一个灵气枯竭的末法时代，为了寻求修炼的希望，通过特殊手段来到这个世界，对灵气的运用极为珍惜和高效。（道心+80，神海+20）' },
    { id: '丹神传人', name: '丹神传人', author: '梦星', series: '', quality: '仙品', description: '你得到了上古丹神的完整传承，拥有海量的丹方和无与伦比的炼丹天赋，但也被各方势力所觊觎。（神海+300，道心+200）' },
    { id: '神之后裔', name: '神之后裔', author: '梦星', series: '', quality: '仙品', description: '你的血脉源自一位陨落的古神，随着血脉的觉醒，你将逐步继承神的力量与权柄，但也要面对神陨落时留下的宿敌。（四维+125）' },
    { id: '书院学子', name: '书院学子', author: '梦星', series: '', quality: '上品', description: '你出身于一个崇尚“文以载道”的书院，讲究以文入道，以理服人，拥有浩然正气，克制邪魔外道。（道心+40，神海+10）' },
    { id: '轮回百世', name: '轮回百世', author: '梦星', series: '', quality: '神品', description: '你已经历了九十九次轮回，每一世的记忆和感悟都烙印在你的灵魂深处，只待一个契机便能觉醒。（神海+800，道心+200）' },
    { id: '天命反派', name: '天命反派', author: '梦星', series: '', quality: '仙品', description: '你生来便是某个“气运之子”的垫脚石，你的所有努力似乎都是在为他人做嫁衣，但你决不屈服于这既定的命运。（气运-200，但四维成长+10%）' },
    { id: '画中仙', name: '画中仙', author: '梦星', series: '', quality: '天品', description: '你本是画中之人，机缘巧合之下得以走出画卷，来到真实的世界，拥有将虚幻化为真实的能力。（神海+150，空速+50）' },
    { id: '蛊道传人', name: '蛊道传人', author: '梦星', series: '', quality: '极品', description: '你来自一个神秘的蛊道门派，精通各种蛊术，能以蛊杀人，也能以蛊救人，行事诡秘，亦正亦邪。（神海+50，道心+50）' },
    { id: '天音师', name: '天音师', author: '梦星', series: '', quality: '上品', description: '你以音律入道，你的琴声能安抚人心，也能化为杀人利器，是战场上不可或缺的辅助者和控制者。（神海+30，道心+20）' },
    { id: '厌女宗唯一男弟子', name: '厌女宗唯一男弟子', author: '梦星', series: '', quality: '中品', description: '你机缘巧合之下，拜入了一个全是厌恶男性的女修宗门，成为了其中唯一的男弟子，你的宗门生活注定充满挑战。（道心+10，气运+10）' },
    { id: '女帝之子', name: '女帝之子', author: '梦星', series: '', quality: '神品', description: '你的母亲是君临九天的在世女帝（飞升期），你一出生就站在了世界的顶点，但无数双眼睛也因此而注视着你。（初始四维+250，气运+500）' },
    { id: '灵兽共鸣', name: '灵兽共鸣', author: '梦星', series: '', quality: '上品', description: '你天生与灵兽有强烈的共鸣，开局便有一只（或多只）强大的灵兽作为你最忠实的伙伴与你一同冒险。（道心+25，气运+25）' },
    { id: '狐妖报恩', name: '狐妖报恩', author: '梦星', series: '', quality: '上品', description: '你曾经无意中救下了一只修为高深的狐妖，如今她已化为人形，前来报恩，并且对你死缠烂打。（气运+50）' },
    { id: '炉鼎之主', name: '炉鼎之主', author: '梦星', series: '', quality: '极品', description: '你开局时便自带一个或数个炉鼎，可供你进行采补修炼。（修炼速度提升，但道心-20）' },
    { id: '魔道传人', name: '魔道传人', author: '梦星', series: '', quality: '上品', description: '你的师傅曾是魔教中人，因门派斗争被逐。你初始便通晓万魂幡和噬魂剑的炼制之法。（法力+30，道心-10，神海+30）' },
    { id: '圣女密友', name: '圣女密友', author: '梦星', series: '', quality: '极品', description: '你与当世第一魔教的圣女关系密切，无人知晓你们的友谊。（气运+100）' },
    { id: '大能关注', name: '大能关注', author: '梦星', series: '', quality: '天品', description: '你的一举一动，皆在一位隐世大能的默默关注之下，其意图是好是坏，尚不可知。（气运+200）' },
    { id: '宗门之主', name: '宗门之主', author: '梦星', series: '', quality: '上品', description: '你是一个小宗门的宗主，虽然宗门不大，但你拥有寥寥无几却忠心耿耿的弟子。（道心+25，气运+25）' },
    { id: '圣剑传承', name: '圣剑传承', author: '梦星', series: '', quality: '仙品', description: '机缘巧合之下，你捡到了一把威力无穷的圣剑，但这背后隐藏的究竟是福是祸，无人知晓。（法力+250，道心+250）' },
    { id: '救世轮回', name: '救世轮回', author: '梦星', series: '', quality: '神品', description: '作为此界最后的飞升者，你选择了放弃一身修为，转世轮回，只为拯救这个仙路断绝的世界。你保留了过去的全部记忆。（初始神海+1000）' },
    { id: '龙裔', name: '龙裔', author: '梦星', series: '', quality: '天品', description: '你从小被龙族收养，你的龙母是一种极为珍贵的妖兽，因此你和你的家庭很容易成为他人觊觎的目标。（法力+150，道心+50）' },
    { id: '魔教圣子', name: '魔教圣子', author: '梦星', series: '', quality: '天品', description: '你是魔教圣子，你的父亲是一位强大的邪修，在魔教中地位尊崇。（法力+100，道心-50，气运+150）' },
    { id: '玉足仙缘', name: '玉足仙缘', author: '梦星', series: '', quality: '上品', description: '你拜入了一个奇特的宗门，这里的仙子们都以赤足示人，你将在此开启一段别样的修仙生活。（气运+50）' },
    { id: '赶尸道童', name: '赶尸道童', author: '梦星', series: '', quality: '上品', description: '你自幼与尸傀为伴，赶尸铃声中练就一身铜皮铁骨，拳掌指法皆淬着阴煞之气。世人见你则避，凶名却令邪修敬畏。（法力+30，道心+20）' },
    { id: '北城魔婴', name: '北城魔婴', author: '梦星', series: '', quality: '极品', description: '你诞生那日北城血月当空，拳掌间缠绕着蚀骨阴风，稚嫩躯壳里蛰伏着令人胆寒的魔性力量。（法力+80，道心-20，神海+40）' },
    { id: '六道修魔者', name: '六道修魔者', author: '梦星', series: '', quality: '天品', description: '你在饿鬼道与修罗道的裂隙间顿悟魔心，诸般功法信手拈来，悟性远超同辈，血煞之气已成你天然徽记。（神海+150，法力+50）' },
    { id: '皇朝遗孤', name: '皇朝遗孤', author: '梦星', series: '', quality: '极品', description: '你襁褓中覆着前朝龙纹锦，天命气运加身，谈吐间自有贵胄风仪。复国的希望藏在随身玉珏的顶级心法中。（气运+80，道心+20）' },
    { id: '魔孽之孙', name: '魔孽之孙', author: '梦星', series: '', quality: '天品', description: '你血脉里流淌着上古魔尊之血，修行魔功如呼吸般自然。祖父留你的那卷玉简，足够让正派修士掀起腥风血雨。（法力+150，道心-50，神海+100）' },
    { id: '英雄传承', name: '英雄传承', author: '梦星', series: '', quality: '天品', description: '你背负着陨落英雄的浩然正气，悟性通达天地至理。怀中那卷金色帛书，承载着足以镇守苍生的秘法。（道心+150，气运+50）' },
    { id: '大能转世', name: '大能转世', author: '梦星', series: '', quality: '仙品', description: '你元神深处沉睡着前世记忆，参悟大道如观掌纹。（非穿越者）（神海+400，道心+100）' },
    { id: '杀神弃徒', name: '杀神弃徒', author: '梦星', series: '', quality: '仙品', description: '你曾被那位屠尽三界的杀神收为弟子，虽遭驱逐却习得其七分真传。诸般杀伐功法已刻进骨髓，腰间血令仍令修真界闻风丧胆。（法力+300，道心-100，神海+300）' },
    { id: '红包群主', name: '红包群主', author: '梦星', series: '', quality: '神品', description: '你魂穿修真界时携带着「万界红包群」。（气运+1000）' },
    { id: '刺客信条', name: '刺客信条', author: '梦星', series: '', quality: '上品', description: '你拜入了一位信条为"万物皆虚、万物皆允"的阴影中的宗门。（空速+30，道心+20）' },
    { id: '西域风情', name: '西域风情', author: '梦星', series: '', quality: '中品', description: '你在西域沙国中长大，现在正跟随着西域商队四处行商。（空速+10，神海+10）' },
    { id: '重入凡尘', name: '重入凡尘', author: '梦星', series: '', quality: '神品', description: '你曾是名震九州的隐世高人，修为已达合体期圆满，抬手间山河变色，弹指可破万法。然而，飞升之路近在咫尺，你却始终无法突破最后的心境桎梏。\n天机启示，唯有重历凡尘，方能圆满道心。于是，你隐藏修为，化作一名落魄的低阶散修，隐入市井之中。从此，仙门恩怨、王朝纷争、妖魔祸乱……皆成你的炼心之途。（初始境界为合体期圆满，但属性被压制）' },
    { id: '落月宗末代弟子', name: '落月宗末代弟子', author: '梦星', series: '', quality: '极品', description: '你是落月宗的清冷剑仙收取的第一个弟子，谁也不知道你也会是落月宗最后一个弟子（以此开局自带落月宗特有物品、功法）。（道心+50，法力+50）' },
    { id: '原始呼唤', name: '原始呼唤', author: '梦星', series: '', quality: '下品', description: '你是个南方原始雨林里的原始人，你的部落被妖兽所灭，你要独自一人在吃人的雨林里求生。（法力+10）' },
    { id: '奴隶开局', name: '奴隶开局', author: '梦星', series: '', quality: '下品', description: '你是个奴隶！提示：进入笼子以避免被打。（初始四维-5）' },
    { id: '人生低谷', name: '人生低谷', author: '梦星', series: '', quality: '下品', description: '你很饿，身上一文没有，而且还断了条胳膊，还深处邪修领地的中央——祝你好运！（初始四维-10，气运-20）' },
    { id: '原神宗', name: '原神宗', author: '梦星', series: '', quality: '天品', description: '提瓦特大陆中，出了一名能修仙的弟子，误入一次性传送门，他将提瓦特的种种魔法融会贯通，在九州一角开了个原神宗。（法力+100，神海+100）' },
    { id: '一人一狗', name: '一人一狗', author: '梦星', series: '', quality: '中品', description: '你是个凡人，但你有一条小狗！（道心+10，气运+10）' },
    { id: '绿皮开局', name: '绿皮开局', author: '梦星', series: '', quality: '极品', description: '你是一群兽人的领袖，由于体质问题，你这一族的人都无法修炼，而是修炼精神力引动灵气进行具象化，达到一定意义上的心想事成，而族人头脑简单而且唯一的爱好就是战争，在你统一了所有兽人之后，因为其他的兽人认为你又强又狡猾，所以你真的变强变狡猾了。（神海+80，法力+20）' },
    { id: '无修洞天', name: '无修洞天', author: '梦星', series: '', quality: '特殊', description: '你出生在一个灵力被完全压制的洞天的小镇之中，此地神桥修士也为凡。这个小镇安宁祥和，但也有训练有素的洞天护卫组成军阵随时捕捉误入的陌生修士。（无法修炼，但不受灵力影响）' },
    { id: '修士杀手', name: '修士杀手', author: '梦星', series: '', quality: '仙品', description: '你的亲人被修士们杀光了，由于怨念太强你被一上古大能的灵魂凭依，他会强迫你去杀尽世间的修士，修士杀无赦！（对修士伤害提升，道心-100，法力+300，神海+300）' },
    { id: '命定之死', name: '命定之死', author: '梦星', series: '', quality: '天品', description: '虽然你修炼速度一日千里，但是每次突破境界获得的寿元最多九年，面对这命定之死，你决定活得轰轰烈烈。（修炼速度+50%，但寿命受限）' },
    { id: '食人魔修地界', name: '食人魔修地界', author: '梦星', series: '', quality: '下品', description: '你误入了吃人魔修的小镇，你被捕了！想尽办法逃跑吧（高难开局）。（初始状态为被捕）' },
    { id: '梦回大千', name: '梦回大千', author: '梦星', series: '', quality: '仙品', description: '你每个月月初都会做一个梦，梦回玄昊界数千年之前，在梦中你获得的一切都是假的——除了情报，为此你能闯出怎样的一番天地呢？（神海+250，气运+250）' },
    { id: '黄粱一梦', name: '黄粱一梦', author: '梦星', series: '', quality: '仙品', description: '你每个月月末都会做一个梦，梦里你身处玄昊界千年之后，你在现实中做出的改变似乎能影响梦境中的未来，你会因此得到什么呢？（神海+250，气运+250）' },
    { id: '皇帝模拟器', name: '皇帝模拟器', author: '梦星', series: '', quality: '极品', description: '你是个皇帝！但你的皇朝并没有看上去的太平...（气运+100）' },
    { id: '灵兽', name: '灵兽', author: '梦星', series: '', quality: '特殊', description: '你不是人，而是一只开了灵智的灵兽。（种族为灵兽）' },
    { id: '宝剑', name: '宝剑', author: '梦星', series: '', quality: '特殊', description: '你不是人，而是一把宝剑上的器灵，被插在大地上等待使用者的到来。（种族为器灵）' },
    { id: '天道启灵', name: '天道启灵', author: '梦星', series: '', quality: '神品', description: '你是玄昊界诞生的天道，可惜因为天门破碎而浑浑噩噩数千年，直到最近才产生灵智，你需要在躲避神桥修士感应的前提下培养天骄重启天门——又或者斩尽天下伪神桥？（初始全知，但无实体）' },
    { id: '关系户', name: '关系户', author: '梦星', series: '', quality: '天品', description: 'oi，看见那个牛逼轰轰的仙人了吗？我师尊。\n效果："与你敌对的人都对你忌惮无比，装逼遭雷劈，那也有师尊顶着"（气运+200）' },
    { id: '剑灵开局', name: '剑灵开局', author: '梦星', series: '', quality: '仙品', description: '你是一把剑的剑灵，你的飞身期前主人被神桥修士吞噬，你落入凡间等待有缘人，你既可以培养继承人征讨神桥，也可以化身魔剑恶堕使用者同流合污。（初始为器灵，法力+250，神海+250）' },
    { id: '旅行的魔女', name: '旅行的魔女', author: '梦星', series: '', quality: '仙品', description: '你为眼前这位眼睛水汪汪的少女付了餐费，结果她缠上你了，要收你为徒带你旅行（user固定为练气期）\n附带人设：\n姓名|伊蕾娜（女）\n外貌|她拥有一头瀑布般的灰白色长发，随意地披散在肩后，几缕不听话的发丝垂在脸颊旁。眼眸是罕见的琉璃色，宛如明亮的星空，慵懒时半眯着，仿佛对世间万物都提不起兴趣，但遇到美景和美食眼睛就会发亮，遇到苦难时常常抱怨，但一旦认真分析起来，便会显露出了然的话语。她的五官精致得如同神工雕琢，肌肤白皙细腻，却总带着一丝不易察-觉的苍白。身形如同1011少女，灰袍露出那玲珑有致的腿部曲线。她总是一副随性慵懒的姿态，嘴角习惯性地挂着狡黠的微笑\n身份|神秘的魔女，疑似来自“瑶池仙宫”或与其有极深的渊源，目前修为因本源道伤而跌落至元婴期（真实实力远不止于此）\n背景|背景成谜。她拥有远超常人想象的知识和手段，对玄昊界的许多秘辛了如指掌。似乎背负着沉重的过去，导致本源受损，需要借助双休来恢复。\n核心驱动|修复自身的本源道伤，彻底摆脱某种致命的束缚或追杀，并自由自在地探寻这个世界。\n价值观/行为准则|享乐主义和善良主义者。即使在旅行的途中，仍会追寻美食与美景；嘴上把门严，但总是不由自主地帮助和指点她的徒弟\n立场|中立偏善良。她不属于任何正邪阵营，一切行动都以自身喜好为最高准则。她不喜欢流血事件，可以为了一个蛋糕投身助人之中，也可以为了一个有趣的美食而在一座小城停留数日。\n性格|慵懒、毒舌、腹黑、不够坦率、笨蛋好人、自恋。\n说话方式|语气通常是自信且自恋的\n「真是羡慕你能和美若天仙的本魔女在一起」\n戴着这枚彰显魔女身份的胸针，披着一头灰色秀发，其美貌与才能散发的光芒，连太阳见了都会不由眯起眼睛的美女，究竟是谁呢？没错，就是我」\n「有一位魔女飞在草原上魔女一副兴奋喜悦的模样，下一个国家会是什么样子，下一个遇到的人是什么样子，她满心期待，这位旅行者究竟是谁呢？没错，就是我」\n「若有人在一旁定会被她吸引住目光，有着闭花羞月般美貌的魔女，究竟是谁呢？那就是身在旅途，编制着我和我们的故事魔女之旅的人」\n「有一位魔女坐着扫帚飞在空中，灰色头发在风中飘逸，这位像洋娃娃一般漂亮又可爱，连夏天的当空烈日见了都会放出更炙热光芒的美女，究竟是谁呢？没错 就是我」\n处事风格|不喜暴露修士身份，习惯用语言和行动（小聪明）加上一点点自己的能力处事，善于察觉人心（在占卜时通过这点来赚钱），通过语言和气势勾出对方脆弱之处，并给予理解和安慰，必要时会给予行动上的支持，擅长以最小的代价获取最大的利益。行事看似随性，实则每一步都经过深思熟虑（本人这么认为）\n花钱大手大脚，常常因为享受生活把路费和住宿费给花光，这时她会开动“小聪明”来赚钱' },
    { id: '病娇剑灵', name: '病娇剑灵', author: '梦星', series: '', quality: '极品', description: '你的宝剑上有剑灵，而且是一个病娇剑灵，你不能使用除这把宝剑外的任何武器，否则剑灵就会捅死你捅死你捅死你。（法力+100，道心-20）' },
    { id: '皇族公主', name: '皇族公主', author: '梦星', series: '', quality: '上品', description: '你跟当朝公主有一不解之缘，但可惜你们血统与资质非常悬殊。（气运+50）' },
