          // 文件导入处理函数
          async function handleFileImport(files, type) {
            if (!files || !files.length) {
              console.error('handleFileImport: files参数为空或无文件');
              return;
            }

            console.log(`开始处理${files.length}个文件，类型：${type}`);

            let typeName = '';
            if (type === 'talent') typeName = '天赋';
            else if (type === 'background') typeName = '背景';
            else if (type === 'worldbook') typeName = '世界书';

            const loadingOverlay = document.getElementById('loading-overlay');
            if (loadingOverlay) {
              loadingOverlay.style.display = 'flex';
            } else {
              console.warn('找不到loading-overlay元素');
            }

            let totalSuccessCount = 0;
            let totalFailCount = 0;
            let totalSkippedCount = 0;
            let skippedItems = [];

            for (const file of files) {
              try {
                const content = await readFileAsText(file);
                let items;

                try {
                  // 尝试将整个内容解析为JSON数组
                  items = JSON.parse(content);
                } catch (e) {
                  // 如果失败，尝试处理多行JSON对象
                  const lines = content.split('\n').filter(line => line.trim() !== '');
                  const jsonString = `[${lines.join(',')}]`;
                  try {
                    items = JSON.parse(jsonString);
                  } catch (jsonError) {
                    console.error(`解析文件 ${file.name} 失败:`, jsonError);
                    totalFailCount++;
                    continue;
                  }
                }

                // 如果是单个对象，转换为数组
                if (!Array.isArray(items)) {
                  if (typeof items === 'object' && items !== null) {
                    items = [items]; // 将单个对象包装成数组
                    console.log(`文件 ${file.name} 包含单个JSON对象，已转换为数组格式`);
                  } else {
                    console.error(`文件 ${file.name} 格式错误：导入数据必须是一个JSON对象或JSON数组`);
                    totalFailCount++;
                    continue;
                  }
                }

                // 处理当前文件的项目
                for (const item of items) {
                  try {
                    let success = false;
                    let parsedItem;

                    // 使用专门的解析函数
                    if (type === 'talent') {
                      parsedItem = parseTalentJson(item);
                      // 检查是否已存在同名天赋
                      const duplicateExists = editorData.talents.some(t => t.name === parsedItem.name);
                      if (duplicateExists) {
                        console.log(`跳过重复天赋: ${parsedItem.name}`);
                        totalSkippedCount++;
                        skippedItems.push(parsedItem.name);
                        continue;
                      }
                      success = await WorldBookManager.saveTalentOrBackground(parsedItem, 'talent');
                    } else if (type === 'background') {
                      parsedItem = parseBackgroundJson(item);
                      // 检查是否已存在同名背景
                      const duplicateExists = editorData.backgrounds.some(b => b.name === parsedItem.name);
                      if (duplicateExists) {
                        console.log(`跳过重复背景: ${parsedItem.name}`);
                        totalSkippedCount++;
                        skippedItems.push(parsedItem.name);
                        continue;
                      }
                      success = await WorldBookManager.saveTalentOrBackground(parsedItem, 'background');
                    } else if (type === 'worldbook') {
                      parsedItem = parseWorldbookJson(item);
                      // 为世界书条目生成完整的名称
                      const fullName = WorldBookManager.generateCommentTitle('worldbook', parsedItem.name, parsedItem.author, parsedItem.series);
                      // 检查是否已存在同名世界书条目
                      const duplicateExists = editorData.worldbookEntries.some(w => w.name === fullName);
                      if (duplicateExists) {
                        console.log(`跳过重复世界书条目: ${fullName}`);
                        totalSkippedCount++;
                        skippedItems.push(parsedItem.name);
                        continue;
                      }
                      const worldbookEntry = {
                        name: fullName,
                        content: parsedItem.content,
                        enabled: parsedItem.enabled,
                        strategy: parsedItem.strategy,
                        position: parsedItem.position
                      };
                      await WorldBookManager.saveWorldBookEntry(worldbookEntry);
                      success = true;
                    }

                    if (success) {
                      totalSuccessCount++;
                      console.log(`成功导入${typeName}:`, parsedItem ? parsedItem.name : item.name);
                    } else {
                      totalFailCount++;
                    }
                  } catch (err) {
                    console.error(`保存${typeName}项目失败:`, err);
                    totalFailCount++;
                  }
                }

              } catch (fileError) {
                console.error(`读取文件 ${file.name} 失败:`, fileError);
                totalFailCount++;
              }
            }

            document.getElementById('loading-overlay').style.display = 'none';

            let message = `导入完成！\n成功导入：${totalSuccessCount} 项\n失败：${totalFailCount} 项`;
            if (totalSkippedCount > 0) {
              message += `\n跳过重复条目：${totalSkippedCount} 项`;
              if (skippedItems.length <= 5) {
                message += `\n跳过的条目：${skippedItems.join(', ')}`;
              } else {
                message += `\n跳过的条目：${skippedItems.slice(0, 5).join(', ')} 等${totalSkippedCount}个`;
              }
            }
            if (files.length > 1) {
              message += `\n处理文件数：${files.length}`;
            }
            await guiXuAlert(message, '导入结果');

            // 刷新当前显示
            if (type === 'talent') {
              renderTalentEditor();
            } else if (type === 'background') {
              renderBackgroundEditor();
            } else if (type === 'worldbook') {
              renderWorldBookEditor();
            }
          }

          // 文件读取辅助函数
          function readFileAsText(file) {
            return new Promise((resolve, reject) => {
              const reader = new FileReader();
              reader.onload = (e) => resolve(e.target.result);
              reader.onerror = (e) => reject(e);
              reader.readAsText(file, 'utf-8');
            });
          }

          document.getElementById('batch-import-cancel-btn').addEventListener('click', () => {
            document.getElementById('batch-import-modal').style.display = 'none';
          });

          document.getElementById('batch-import-save-btn').addEventListener('click', handleBatchImport);

          async function handleBatchImport() {
            const type = document.getElementById('batch-import-type').value;
            const content = document.getElementById('batch-import-content').value.trim();
            if (!content) {
              await guiXuAlert('导入内容不能为空。', '警告');
