              const lines = content.split('\n').filter(line => line.trim() !== '');
              const jsonString = `[${lines.join(',')}]`;
              try {
                items = JSON.parse(jsonString);
              } catch (jsonError) {
                await guiXuAlert('解析JSON失败，请检查格式。确保是有效的JSON数组或每行一个JSON对象。', '错误');
                console.error('JSON Parsing Error:', jsonError);
                return;
              }
            }

            // 如果是单个对象，转换为数组
            if (!Array.isArray(items)) {
              if (typeof items === 'object' && items !== null) {
                items = [items]; // 将单个对象包装成数组
                console.log('检测到单个JSON对象，已转换为数组格式');
              } else {
                await guiXuAlert('导入数据必须是一个JSON对象或JSON数组。', '错误');
                return;
              }
            }

            let successCount = 0;
            let failCount = 0;
            let skippedCount = 0;
            let skippedItems = [];
            document.getElementById('loading-overlay').style.display = 'flex';

            for (const item of items) {
              try {
                let success = false;

                // 检查是否已存在同名条目
                const itemName = item.name || item.id || '';
                let duplicateExists = false;

                if (type === 'talent') {
                  duplicateExists = editorData.talents.some(t => t.name === itemName);
                } else if (type === 'background') {
                  duplicateExists = editorData.backgrounds.some(b => b.name === itemName);
                } else if (type === 'worldbook') {
                  const fullName = WorldBookManager.generateCommentTitle('worldbook', itemName, item.author || '未知', item.series || '');
                  duplicateExists = editorData.worldbookEntries.some(w => w.name === fullName);
