    // 统一存档保存函数
    async function savesToStorage(saveData) {
        try {
            if (StorageModeManager.currentMode === 'indexedDB') {
                return await IndexedDBManager.saveToIndexedDB(saveData);
            } else {
                const allSaves = await getSavesFromStorage();
                allSaves[saveData.id] = saveData;
                localStorage.setItem('guixu_multi_save_data', JSON.stringify(allSaves));
                return true;
            }
        } catch (error) {
            console.error('保存存档失败:', error);
            return false;
        }
    }

    // 统一存档删除函数
    async function deleteFromStorage(slotId) {
        try {
            if (StorageModeManager.currentMode === 'indexedDB') {
                return await IndexedDBManager.deleteFromIndexedDB(slotId);
            } else {
                const allSaves = await getSavesFromStorage();
                delete allSaves[slotId];
                localStorage.setItem('guixu_multi_save_data', JSON.stringify(allSaves));
                return true;
            }
        } catch (error) {
            console.error('删除存档失败:', error);
            return false;
        }
    }

    // 统一存档清空函数
    async function clearAllFromStorage() {
        try {
            if (StorageModeManager.currentMode === 'indexedDB') {
                return await IndexedDBManager.clearAllFromIndexedDB();
            } else {
                localStorage.removeItem('guixu_multi_save_data');
                return true;
            }
        } catch (error) {
            console.error('清空存档失败:', error);
            return false;
        }
    }

    // --- START OF SAVE/LOAD MANAGER LOGIC ---
    function _getDisplayText(aiResponse) {
        try {
            if (!aiResponse || typeof aiResponse !== 'string') return '';
            const gameTextMatch = /<gametxt>([\s\S]*?)<\/gametxt>/i.exec(aiResponse);
            if (gameTextMatch && gameTextMatch[1]) {
                const commentRegex = new RegExp('<!--[\\s\\S]*?-->', 'g');
                return gameTextMatch[1].replace(commentRegex, '').trim();
            }
            return aiResponse.replace(/<\/?(本世历程|往世涟漪|UpdateVariable|角色提取|thinking|gametxt|开局设定|行动选项|action)[\s\S]*?>/gi, '').trim();
        } catch (e) {
            console.error("解析显示文本时出错:", e);
            return "[摘要解析失败]";
        }
    }

    async function getSavesFromStorage() {
        try {
            if (StorageModeManager.currentMode === 'indexedDB') {
                return await IndexedDBManager.getAllFromIndexedDB();
            } else {
                const saves = localStorage.getItem('guixu_multi_save_data');
                return saves ? JSON.parse(saves) : {};
            }
        } catch (e) {
            console.error("获取存档失败:", e);
            guiXuAlert('错误：主存档文件已损坏，无法读取。', '错误');
            return {};
        }
    }

