                    const duplicateIndex = worldbook.findIndex(e => e.name === entry.name);
                    if (duplicateIndex > -1) {
                      worldbook[duplicateIndex] = { ...worldbook[duplicateIndex], ...entry };
                      console.log(`覆盖同名世界书条目: ${entry.name}`);
                    } else {
                      worldbook.push(entry);
                      console.log(`添加新世界书条目: ${entry.name}`);
                    }
                    return worldbook;
                  });
                }
                merged++;
              }
              cloudPending[pageKey] = [];
              await loadEditorData();
              renderCloudDatabaseList();
              await guiXuAlert(`已加入 ${merged} 项`, '完成');
            } else {
              // 预设页面：直接使用预设编辑器的handleImportFile处理

              for (const preset of pendings) {
                console.log(`=== 处理预设: ${preset.name} ===`);
                console.log('preset结构检查:', {
                  hasType: !!preset.type,
                  hasData: !!preset.data,
                  hasLocalTalents: !!preset.localTalents,
                  hasLocalBackgrounds: !!preset.localBackgrounds,
                  hasWorldBook: !!preset.worldBook,
                  localTalentsLength: Array.isArray(preset.localTalents) ? preset.localTalents.length : 'N/A',
                  localBackgroundsLength: Array.isArray(preset.localBackgrounds) ? preset.localBackgrounds.length : 'N/A',
                  worldBookLength: Array.isArray(preset.worldBook) ? preset.worldBook.length : 'N/A'
                });

                // 直接使用预设编辑器的handleImportFile处理，避免重复的格式检测逻辑
                let fileContent;
                if (preset._originalData) {
                  // 使用保存的原始数据
                  fileContent = JSON.stringify(preset._originalData);
                } else {
                  // 使用当前预设数据
                  fileContent = JSON.stringify(preset);
                }

                console.log('转换为文件内容调用handleImportFile处理');
                await handleImportFile(fileContent);

                // handleImportFile已经完成所有处理，跳过后续逻辑避免重复保存
                continue;
              }

              // 清理pending并刷新界面
              cloudPending[pageKey] = [];
              await loadEditorData();
              renderCloudDatabaseList();
            }
          } catch (err) {
            console.error('确认新增失败', err);
