          if (action === 'cloud-add') {
            const pageKey = page;
            const dataset = pageKey === 'talent' ? (latestCloudData?.talents || [])
              : pageKey === 'background' ? (latestCloudData?.backgrounds || [])
              : pageKey === 'worldbook' ? (latestCloudData?.worldbookEntries || [])
              : (latestCloudData?.presets || []);
            const picked = dataset.find(d => String(d.name) === String(name));
            if (picked) {
              // 所有类型都使用pending机制
              cloudPending[pageKey] = cloudPending[pageKey] || [];
              // 去重：按名称判定
              if (!cloudPending[pageKey].some(x => String(x.name) === String(picked.name))) {
                cloudPending[pageKey].push(picked);
              }
              renderCloudDatabaseList();
            }
            return;
          }
        }
