            '神品': current5StarRate * 0.5,
            '仙品': current5StarRate * 0.5,
            '天品': base4StarRate * 0.5,
            '极品': base4StarRate * 0.5,
            '上品': remainingRate * 0.20,
            '中品': remainingRate * 0.20,
            '下品': remainingRate * 0.30,
            '凡品': remainingRate * 0.30,
        };
    }
